head.b:skin:
/* Blogger Template Skin Requirement - Main Styles Below */
#blogger-hidden-section { display: none !important; }
.navbar, .blog-feeds, .feed-links { display: none !important; }

div.style:
position: fixed;
bottom: calc(20px + env(safe-area-inset-bottom, 0px));
right: 20px;
width: 60px;
height: 60px;
background: #66021F;
border-radius: 50%;
display: flex;
justify-content: center;
align-items: center;
z-index: 2147483647;
cursor: pointer;
box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
visibility: hidden;
opacity: 0;
transition: visibility 0s, opacity 0.3s ease-in-out;

body.script:
//
  document.addEventListener('DOMContentLoaded', function () {

    /* ------------------------------------------------------------------------
       HELPER: CONVERT ENGLISH DIGITS TO BANGLA DIGITS
       ------------------------------------------------------------------------ */
    const banglaDigits = ['০', '১', '২', '৩', '৪', '৫', '৬', '৭', '৮', '৯'];
    function toBanglaNumber(numStr) {
      return String(numStr).replace(/\d/g, function (d) {
        return banglaDigits[d];
      });
    }

    /* ------------------------------------------------------------------------
       1. AUTO-PLAY COUPLE HERO VIDEO
       ------------------------------------------------------------------------ */
    const bgVideo = document.getElementById('bgVideo3');
    if (bgVideo) {
      bgVideo.play().catch(function () {});
      document.addEventListener('touchstart', function () {
        if (bgVideo.paused) bgVideo.play().catch(function () {});
      }, { once: true });
    }

    /* ------------------------------------------------------------------------
       2. ENVELOPE OPENING ANIMATION + AUDIO PLAYER + HERO REVEAL
       ------------------------------------------------------------------------ */
    const envRec = document.getElementById('rec2052880283');
    const sealElem = document.querySelector('#rec2052880283 [data-elem-id="1773847037346"]');
    const textElem = document.querySelector('#rec2052880283 [data-elem-id="1773926384566"]');
    const topFlap = document.querySelector('#rec2052880283 [data-elem-id="1773847892509"]');
    const bottomFlap = document.querySelector('#rec2052880283 [data-elem-id="1773847988093"]');
    const leftFlap = document.querySelector('#rec2052880283 [data-elem-id="1773848179361"]');
    const rightFlap = document.querySelector('#rec2052880283 [data-elem-id="1773848137949"]');

    const audio = document.getElementById('invitation-audio');
    const audioControl = document.getElementById('audio-control');
    const iconPlay = document.getElementById('icon-play');
    const iconPause = document.getElementById('icon-pause');

    let envelopeOpened = false;

    function triggerHeroAnimations() {
      const heroAnims = document.querySelectorAll('.js-delay-anim');
      heroAnims.forEach(function (el) {
        const duration = parseFloat(el.getAttribute('data-animate-duration') || '2');
        const delay = parseFloat(el.getAttribute('data-animate-delay') || '3');
        el.style.transition = 'transform ' + duration + 's cubic-bezier(0.19, 1, 0.22, 1) ' + delay + 's, opacity ' + duration + 's cubic-bezier(0.19, 1, 0.22, 1) ' + delay + 's';
        requestAnimationFrame(function () {
          el.classList.add('t-animate_started');
        });
      });
    }

    function openEnvelope() {
      if (envelopeOpened) return;
      envelopeOpened = true;

      // Play Audio & Reveal Floating Button
      if (audio) {
        audio.muted = false;
        audio.play().then(function () {
          iconPlay.style.display = 'none';
          iconPause.style.display = 'block';
        }).catch(function (err) {
          console.log('Audio play failed:', err);
        });
      }
      if (audioControl) {
        audioControl.style.visibility = 'visible';
        audioControl.style.opacity = '1';
      }

      // Play Video if paused
      if (bgVideo && bgVideo.paused) {
        bgVideo.play().catch(function () {});
      }

      // Trigger Envelope Step-by-Step Animations
      if (textElem) textElem.classList.add('env-anim-text');
      if (sealElem) sealElem.classList.add('env-anim-seal');
      if (topFlap) topFlap.classList.add('env-anim-top');
      if (bottomFlap) bottomFlap.classList.add('env-anim-bottom');
      if (leftFlap) leftFlap.classList.add('env-anim-left');
      if (rightFlap) rightFlap.classList.add('env-anim-right');

      // Trigger Hero Delayed Animations (3s delay matches envelope opening)
      triggerHeroAnimations();

      // Unlock scroll when flaps start parting (at 2600ms) and hide overlay after completion (5000ms)
      setTimeout(function () {
        document.body.classList.remove('envelope-locked');
      }, 2600);

      setTimeout(function () {
        if (envRec) envRec.classList.add('envelope-done');
      }, 5000);
    }

    function handleEnvelopeKey(e) {
      if (e.key === 'Enter' || e.key === ' ' || e.key === 'Spacebar') {
        e.preventDefault();
        openEnvelope();
      }
    }

    if (sealElem) {
      sealElem.addEventListener('click', openEnvelope);
      sealElem.addEventListener('keydown', handleEnvelopeKey);
    }
    if (textElem) {
      textElem.addEventListener('click', openEnvelope);
      textElem.addEventListener('keydown', handleEnvelopeKey);
    }

    if (audioControl && audio) {
      function toggleAudio() {
        if (audio.paused) {
          audio.play().then(function () {
            iconPlay.style.display = 'none';
            iconPause.style.display = 'block';
          }).catch(function (err) {
            console.log('Audio resume error:', err);
          });
        } else {
          audio.pause();
          iconPlay.style.display = 'block';
          iconPause.style.display = 'none';
        }
      }
      audioControl.addEventListener('click', toggleAudio);
      audioControl.addEventListener('keydown', function (e) {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          toggleAudio();
        }
      });
    }

    /* ------------------------------------------------------------------------
       3. LIVE COUNTDOWN TIMER IN BANGLA DIGITS (Target: July 05, 2026 16:00:00)
       ------------------------------------------------------------------------ */
    // Fixed: Synchronized with header date '০৫.০৭.২৬' & reception start at 16:00
    const eventLocal = new Date(2026, 6, 5, 16, 0, 0);
    function updateCountdown() {
      const now = new Date();
      const distance = eventLocal - now;
      const container = document.getElementById('countdownContainer');
      if (!container) return;

      if (distance < 0) {
        container.innerHTML = 'শুভক্ষণ উপস্থিত!';
        return;
      }
      const d = String(Math.floor(distance / (1000 * 60 * 60 * 24))).padStart(2, '0');
      const h = String(Math.floor((distance % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60))).padStart(2, '0');
      const m = String(Math.floor((distance % (1000 * 60 * 60)) / (1000 * 60))).padStart(2, '0');
      const s = String(Math.floor((distance % (1000 * 60)) / 1000)).padStart(2, '0');

      document.getElementById('days').textContent = toBanglaNumber(d);
      document.getElementById('hours').textContent = toBanglaNumber(h);
      document.getElementById('minutes').textContent = toBanglaNumber(m);
      document.getElementById('seconds').textContent = toBanglaNumber(s);
    }
    updateCountdown();
    setInterval(updateCountdown, 1000);

    /* ------------------------------------------------------------------------
       4. SCROLL-TRIGGERED ANIMATIONS (.t-animate & Pendulum Polaroids)
       ------------------------------------------------------------------------ */
    const scrollAnimElements = document.querySelectorAll('.t-animate:not(.js-delay-anim)');
    const animObserver = new IntersectionObserver(function (entries) {
      entries.forEach(function (entry) {
        if (entry.isIntersecting) {
          const el = entry.target;
          const duration = parseFloat(el.getAttribute('data-animate-duration') || '2');
          const delay = parseFloat(el.getAttribute('data-animate-delay') || '0');
          el.style.transition = 'transform ' + duration + 's cubic-bezier(0.19, 1, 0.22, 1) ' + delay + 's, opacity ' + duration + 's cubic-bezier(0.19, 1, 0.22, 1) ' + delay + 's';
          el.classList.add('t-animate_started');
          animObserver.unobserve(el);
        }
      });
    }, { threshold: 0.15 });

    scrollAnimElements.forEach(function (el) {
      animObserver.observe(el);
    });

    // Polaroids Pendulum Swing Observer (threshold lowered to 0.1 for mobile reliability)
    const polaroidGroom = document.getElementById('polaroidGroom');
    const polaroidBride = document.getElementById('polaroidBride');
    const polaroidObserver = new IntersectionObserver(function (entries) {
      entries.forEach(function (entry) {
        if (entry.isIntersecting) {
          if (entry.target.id === 'polaroidGroom') {
            entry.target.classList.add('swing-groom-active');
          } else if (entry.target.id === 'polaroidBride') {
            entry.target.classList.add('swing-bride-active');
          }
          polaroidObserver.unobserve(entry.target);
        }
      });
    }, { threshold: 0.1 });

    if (polaroidGroom) polaroidObserver.observe(polaroidGroom);
    if (polaroidBride) polaroidObserver.observe(polaroidBride);

    /* ------------------------------------------------------------------------
       5. SCHEDULE OF EVENTS: SCROLL-LINKED 3D HEART (THROTTLED WITH rAF)
       ------------------------------------------------------------------------ */
    const scrollHeartElem = document.getElementById('scrollHeartElem');
    const scheduleRec = document.getElementById('rec2002506421');

    function updateHeartOnScroll() {
      if (!scrollHeartElem || !scheduleRec) return;
      const rect = scheduleRec.getBoundingClientRect();
      const heartBaseTop = rect.top + 95;
      const triggerLine = window.innerHeight * 0.5;
      const scrolledPast = triggerLine - heartBaseTop;

      const maxTravel = 247;
      let targetY = 0;
      if (scrolledPast <= 0) {
        targetY = 0;
      } else if (scrolledPast <= 100) {
        targetY = (scrolledPast / 100) * 80;
      } else if (scrolledPast <= 200) {
        targetY = 80 + ((scrolledPast - 100) / 100) * (169 - 80);
      } else if (scrolledPast <= 300) {
        targetY = 169 + ((scrolledPast - 200) / 100) * (maxTravel - 169);
      } else {
        targetY = maxTravel;
      }

      scrollHeartElem.style.transform = 'translate3d(0, ' + targetY.toFixed(2) + 'px, 0)';
    }

    let heartTicking = false;
    function onScrollHeartTick() {
      if (!heartTicking) {
        window.requestAnimationFrame(function () {
          updateHeartOnScroll();
          heartTicking = false;
        });
        heartTicking = true;
      }
    }

    window.addEventListener('scroll', onScrollHeartTick, { passive: true });
    window.addEventListener('resize', onScrollHeartTick, { passive: true });
    updateHeartOnScroll();

    /* ------------------------------------------------------------------------
       6. RSVP POPUP MODAL & FORM HANDLER (WITH LOCALSTORAGE & WHATSAPP SYNC)
       ------------------------------------------------------------------------ */
    const openRsvpBtn = document.getElementById('openRsvpBtn');
    const closeRsvpBtn = document.getElementById('closeRsvpBtn');
    const rsvpPopupModal = document.getElementById('rsvpPopupModal');
    const rsvpForm = document.getElementById('form2052858183');
    const rsvpSuccessBox = document.getElementById('rsvpSuccessBox');
    const rsvpWhatsAppWrap = document.getElementById('rsvpWhatsAppWrap');
    const rsvpWhatsAppBtn = document.getElementById('rsvpWhatsAppBtn');

    function closeRsvpModal() {
      if (rsvpPopupModal) {
        rsvpPopupModal.classList.remove('t-popup_show');
        document.body.style.overflow = '';
      }
    }

    function openRsvpModal() {
      if (rsvpPopupModal) {
        rsvpPopupModal.classList.add('t-popup_show');
        document.body.style.overflow = 'hidden';
        const firstInput = document.getElementById('input_5828866651120');
        if (firstInput) setTimeout(function () { firstInput.focus(); }, 120);
      }
    }

    if (openRsvpBtn && rsvpPopupModal) {
      openRsvpBtn.addEventListener('click', function (e) {
        e.preventDefault();
        openRsvpModal();
      });
    }

    if (closeRsvpBtn && rsvpPopupModal) {
      closeRsvpBtn.addEventListener('click', closeRsvpModal);
    }

    if (rsvpPopupModal) {
      rsvpPopupModal.addEventListener('click', function (e) {
        if (e.target === rsvpPopupModal) {
          closeRsvpModal();
        }
      });
    }

    // Close modal on Escape key press
    document.addEventListener('keydown', function (e) {
      if (e.key === 'Escape' && rsvpPopupModal && rsvpPopupModal.classList.contains('t-popup_show')) {
        closeRsvpModal();
      }
    });

    if (rsvpForm) {
      rsvpForm.addEventListener('submit', function (e) {
        e.preventDefault();

        const nameInput = document.getElementById('input_5828866651120');
        const guestName = (nameInput ? nameInput.value : '').trim();
        const attendanceEl = document.querySelector('input[name="attendance"]:checked');
        const attendance = attendanceEl ? attendanceEl.value : '';
        const foodInput = document.getElementById('input_5828866651122');
        const foodPref = (foodInput ? foodInput.value : '').trim() || 'কোনো অ্যালার্জি নেই';

        if (!guestName) {
          alert('অনুগ্রহ করে আপনার নাম লিখুন।');
          if (nameInput) nameInput.focus();
          return;
        }
        if (!attendance) {
          alert('অনুগ্রহ করে আপনি আসছেন কিনা তা নিশ্চিত করুন।');
          return;
        }

        const submission = {
          id: 'rsvp_' + Date.now(),
          guestName: guestName,
          attendance: attendance,
          foodPreference: foodPref,
          submittedAt: new Date().toLocaleString('bn-BD', { timeZone: 'Asia/Dhaka' })
        };

        // 1. Permanent Local Storage Backup
        try {
          const currentList = JSON.parse(localStorage.getItem('wedding_rsvps') || '[]');
          currentList.push(submission);
          localStorage.setItem('wedding_rsvps', JSON.stringify(currentList));
          console.log('RSVP saved successfully:', submission);
        } catch (storageErr) {
          console.warn('LocalStorage save failed:', storageErr);
        }

        // 2. Dynamic WhatsApp message generator for immediate notification
        const coordinatorPhone = '8801XXXXXXXXX'; // ⚠️ REPLACE with real couple/coordinator WhatsApp number (include country code, e.g., 88017XXXXXXXX)
        const waMessage = encodeURIComponent(
          `*🎉 বিবাহের নিমন্ত্রণপত্র RSVP কনফার্মেশন*\n\n` +
          `👤 *নাম:* ${submission.guestName}\n` +
          `💌 *উপস্থিতি:* ${submission.attendance}\n` +
          `🍽️ *খাবারের পছন্দ/অ্যালার্জি:* ${submission.foodPreference}\n` +
          `📅 *তারিখ:* ০৫ জুলাই ২০২৬\n` +
          `⏰ *সময়:* ১৬:০০ (বিকেল ৪টা)`
        );

        if (rsvpWhatsAppBtn && rsvpWhatsAppWrap) {
          rsvpWhatsAppBtn.href = 'https://wa.me/' + coordinatorPhone + '?text=' + waMessage;
          rsvpWhatsAppWrap.style.display = 'block';
        }

        if (rsvpSuccessBox) {
          rsvpSuccessBox.style.display = 'block';
        }

        // If user doesn't click WhatsApp within 6 seconds, gracefully close
        setTimeout(function () {
          closeRsvpModal();
          rsvpForm.reset();
          if (rsvpSuccessBox) rsvpSuccessBox.style.display = 'none';
          if (rsvpWhatsAppWrap) rsvpWhatsAppWrap.style.display = 'none';
        }, 6000);
      });
    }

    /* ------------------------------------------------------------------------
       PHASE 4: ICS / Apple Calendar download helper
       ------------------------------------------------------------------------ */
    window.downloadICS = function (e) {
      e.preventDefault();
      var icsContent = [
        'BEGIN:VCALENDAR',
        'VERSION:2.0',
        'PRODID:-//Robiul+Fahmida Wedding//EN',
        'CALSCALE:GREGORIAN',
        'METHOD:PUBLISH',
        'BEGIN:VEVENT',
        'UID:robiul-fahmida-wedding-2026@invitation',
        'DTSTART:20260705T100000Z',
        'DTEND:20260705T160000Z',
        'SUMMARY:\u09b0\u09ac\u09bf\u0989\u09b2 + \u09ab\u09be\u09b9\u09ae\u09bf\u09a6\u09be | \u09ac\u09bf\u09ac\u09be\u09b9\u09be\u09a8\u09c1\u09b7\u09cd\u09a0\u09be\u09a8',
        'DESCRIPTION:\u09b0\u09ac\u09bf\u0989\u09b2 \u098f\u09ac\u0982 \u09ab\u09be\u09b9\u09ae\u09bf\u09a6\u09be\u09b0 \u09ad\u09be\u09b2\u09cb\u09ac\u09be\u09b8\u09be\u09b0 \u09ac\u09bf\u09b6\u09c7\u09b7 \u09a6\u09bf\u09a8\u09c7\u09b0 \u09b0\u09cb\u09ae\u09be\u09a8\u09cd\u099f\u09bf\u0995 \u0986\u09ae\u09a8\u09cd\u09a4\u09cd\u09b0\u09a3\u0964 \u0986\u09aa\u09a8\u09be\u09b0 \u0989\u09aa\u09b8\u09cd\u09a5\u09bf\u09a4\u09bf \u098f\u0995\u09be\u09a8\u09cd\u09a4 \u0995\u09be\u09ae\u09cd\u09af\u0964',
        'LOCATION:Chateau de Paon\\, Petit Chemin de Saint-Gilles\\, 13200 Arles\\, France',
        'STATUS:CONFIRMED',
        'TRANSP:OPAQUE',
        'END:VEVENT',
        'END:VCALENDAR'
      ].join('\r\n');

      try {
        var blob = new Blob([icsContent], { type: 'text/calendar;charset=utf-8' });
        var url = URL.createObjectURL(blob);
        var link = document.createElement('a');
        link.href = url;
        link.download = 'robiul-fahmida-wedding.ics';
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        setTimeout(function () { URL.revokeObjectURL(url); }, 1000);
      } catch (err) {
        // Fallback: data URI for older Safari
        var dataUri = 'data:text/calendar;charset=utf-8,' + encodeURIComponent(icsContent);
        window.open(dataUri);
      }
    };

  });
//
